"""Actual portrait carrier -> owned landscape Activity configuration regression."""
import ast,os,subprocess,sys
from pathlib import Path
root=Path(__file__).resolve().parents[2];out=Path(sys.argv[1]);out.mkdir(parents=True,exist_ok=True)
tree=ast.parse((root/'tools/phone-rotation-jvm/run.py').read_text(encoding='utf-8-sig'))
files=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='FILES' for t in n.targets)) if False else {}
# Reuse the existing native-shaped Android fixtures generated by the viewport suite.
subprocess.run([sys.executable,'-X','utf8',str(root/'tools/phone-rotation-jvm/run.py'),str(out)],check=True)
p=out/'android/content/res/Configuration.java';s=p.read_text().replace('ORIENTATION_PORTRAIT=1','ORIENTATION_LANDSCAPE=2,ORIENTATION_PORTRAIT=1');p.write_text(s)
test=out/'com/jiusis/mistep/SideConfigurationRegression.java'
test.write_text(r'''package com.jiusis.mistep;
import android.content.res.Configuration;import android.graphics.Rect;
public class SideConfigurationRegression {
 static int checks;static void check(boolean b,String s){checks++;if(!b)throw new AssertionError(s);}
 static class Task {Rect bounds=new Rect(0,0,1080,2460);int mode=6;boolean force=true;Object getBounds(){return bounds;}int getWindowingMode(){return mode;}boolean isForceTranslucent(){return force;}}
 static class Activity {Configuration resolved=new Configuration();Object getResolvedOverrideConfiguration(){return resolved;}}
 public static void main(String[]args){for(int direction:new int[]{1,3}){
 Task t=new Task();Activity a=new Activity();Configuration local=new Configuration();local.orientation=2;local.densityDpi=440;local.screenWidthDp=894;local.screenHeightDp=380;local.smallestScreenWidthDp=380;
 local.windowConfiguration.setBounds(new Rect(0,0,2460,1080));local.windowConfiguration.setAppBounds(new Rect(0,35,2460,1080));local.windowConfiguration.setDisplayRotation(direction);
 a.resolved.orientation=1;a.resolved.screenWidthDp=392;a.resolved.screenHeightDp=894;a.resolved.windowConfiguration.setBounds(new Rect(t.bounds));a.resolved.windowConfiguration.setAppBounds(new Rect(t.bounds));int seq=a.resolved.seq;
 check(MiStepSideConfiguration.apply(a,t,local),"owned landscape repaired");check(a.resolved.orientation==2&&a.resolved.screenWidthDp>a.resolved.screenHeightDp,"client resource qualifiers stay landscape");check(a.resolved.windowConfiguration.getAppBounds().equals(new Rect(0,35,2460,1080)),"native rotated app/inset bounds used");check(t.bounds.equals(new Rect(0,0,1080,2460))&&t.mode==6,"physical TaskView carrier unchanged");check(a.resolved.seq==seq,"native sequence unchanged");
 a.resolved.windowConfiguration.setAppBounds(new Rect(0,50,2400,1060));MiStepSideConfiguration.apply(a,t,local);check(a.resolved.windowConfiguration.getAppBounds().equals(new Rect(0,50,2400,1060)),"already rotated native inset geometry preserved");
 for(int mode:new int[]{1,5}){t.mode=mode;check(!MiStepSideConfiguration.apply(a,t,local),"other window mode excluded");}t.mode=6;t.force=false;check(!MiStepSideConfiguration.apply(a,t,local),"unowned mode6 excluded");t.force=true;local.orientation=1;check(!MiStepSideConfiguration.apply(a,t,local),"portrait remains native");
 }System.out.println("Production side landscape configuration: "+checks+" checks passed");}
}''',encoding='utf-8')
jdk=Path(os.environ['MISTEP_JAVA_BIN']);subprocess.run([str(jdk/'javac.exe'),'-encoding','UTF-8','--release','17','-cp',str(out),'-d',str(out),str(p),str(root/'module/src/main/java/com/jiusis/mistep/MiStepSideConfiguration.java'),str(test)],check=True)
subprocess.run([str(jdk/'java.exe'),'-cp',str(out),'com.jiusis.mistep.SideConfigurationRegression'],check=True)
